124	async function makeClaim(
125	  chainId: number,
126	  epoch: number,
127	  epochPeriod: number,
128	  transactionHandler: ITransactionHandler,
129	  veaInbox: any,
130	  veaOutbox: any,
131	  queryRpc: JsonRpcProvider,
132	  emitter: EventEmitter,
133	  fetchLatestClaimedEpoch: typeof getLastClaimedEpoch = getLastClaimedEpoch,
134	  fetchBlocksAndCheckFinality: typeof getBlocksAndCheckFinality,
135	  fetchSettledReadBlocks: typeof resolveSettledReadBlocks = resolveSettledReadBlocks
136	): Promise<ITransactionHandler | null> {
137	  // Claiming stakes a deposit on the snapshot we are about to read, so resolve
138	  // the settled blocks first and read only at them.
139	  const settledBlocks = await fetchSettledReadBlocks({
140	    inboxProvider: transactionHandler.veaInboxProvider,
141	    outboxProvider: queryRpc,
142	    epoch,
143	    epochPeriod,
144	    emitter: emitter as any,
145	    fetchBlocksAndCheckFinality,
146	  });
147	  if (!settledBlocks) return null;
148	
149	  const savedSnapshot = await veaInbox.snapshots(epoch, { blockTag: settledBlocks.inboxBlock });
150	  if (savedSnapshot == ethers.ZeroHash) {
151	    return null;
152	  }
153	  const outboxStateRoot = await veaOutbox.stateRoot({ blockTag: settledBlocks.outboxBlock });
154	  let lastClaimedStateroot: string | null = null;
155	  try {
156	    const [floorBlock, headBlock] = await Promise.all([
157	      getLookbackFloorBlock({ provider: queryRpc, chainId, epochPeriod }),
158	      queryRpc.getBlock("finalized"),
159	    ]);
160	    const lastClaimLog = await findLatestLog({
161	      contract: veaOutbox,
162	      filter: veaOutbox.filters.Claimed(),
163	      fromBlock: floorBlock,
164	      toBlock: headBlock.number,
165	    });
166	    lastClaimedStateroot = lastClaimLog?.data ?? null;
167	  } catch {
168	    const claimData = await fetchLatestClaimedEpoch(veaOutbox.target, chainId);
169	    lastClaimedStateroot = claimData ? claimData.stateRoot : ethers.ZeroHash;
170	  }
171	  if (lastClaimedStateroot == null) {
172	    return null;
173	  }
174	  const newMessagesToBridge = savedSnapshot != outboxStateRoot && savedSnapshot != lastClaimedStateroot;
175	  if (newMessagesToBridge) {
176	    await transactionHandler.makeClaim(savedSnapshot);
177	    return transactionHandler;
178	  }
179	  return null;
180	}
