21	 * Query a contract's logs over a block range in bounded chunks.
22	 *
23	 * Every provider caps `eth_getLogs` at some range width, and the cap differs
24	 * between providers. Rather than hardcode a guess, the scanner starts at
25	 * `chunkSize` and halves it whenever the provider rejects a chunk, keeping the
26	 * narrowed size for the rest of the scan. Below `minChunkSize` the provider
27	 * error is rethrown, so a genuinely broken endpoint still surfaces.
28	 */
29	export const scanLogs = async ({
30	  contract,
31	  filter,
32	  fromBlock,
33	  toBlock,
34	  chunkSize = DEFAULT_CHUNK_SIZE,
35	  minChunkSize = MIN_CHUNK_SIZE,
36	  direction = "forward",
37	  stopOnFirstHit = false,
38	}: ScanLogsParams): Promise<any[]> => {
39	  const logs: any[] = [];
40	  if (toBlock < fromBlock) return logs;
41	
42	  const forward = direction === "forward";
43	  let size = chunkSize;
44	  let cursor = forward ? fromBlock : toBlock;
45	
46	  while (forward ? cursor <= toBlock : cursor >= fromBlock) {
47	    const lo = forward ? cursor : Math.max(cursor - size + 1, fromBlock);
48	    const hi = forward ? Math.min(cursor + size - 1, toBlock) : cursor;
49	    try {
50	      const chunk = await contract.queryFilter(filter, lo, hi);
51	      logs.push(...chunk);
52	      if (stopOnFirstHit && chunk.length > 0) break;
53	      cursor = forward ? hi + 1 : lo - 1;
54	    } catch (error) {
55	      if (size <= minChunkSize) throw error;
56	      size = Math.max(Math.floor(size / 2), minChunkSize);
57	    }
58	  }
