  // arbToGnosis: the outbox is on Chiado while the router is on Sepolia.
  // Their block numbers are unrelated, so a router block applied to the
  // outbox scans an empty range and the bot never claims.
  const ROUTER_HEAD = 7_000_000; // Sepolia scale
  const OUTBOX_HEAD = 30_000_000; // Chiado scale
  const SEC_PER_BLOCK = 5;
  const queriedRanges: Array<[number, number]> = [];

  veaInbox.snapshots = jest.fn().mockResolvedValue("0x7890");
  veaOutbox.stateRoot = jest.fn().mockResolvedValue("0xstateroot");
  veaOutbox.filters = { Claimed: jest.fn(() => ({ event: "Claimed" })) };
  veaOutbox.queryFilter = jest.fn(async (_filter: any, from: number, to: number) => {
    queriedRanges.push([from, to]);
    return [];
  });

  const veaRouterProvider: any = {
    getBlock: jest.fn(async (tag: any) => {
      const number = typeof tag === "number" ? tag : ROUTER_HEAD;
      return { number, timestamp: number * 12 };
    }),
  };
  veaOutboxProvider.getBlock = jest.fn(async (tag: any) => {
    const number = typeof tag === "number" ? tag : OUTBOX_HEAD;
    return { number, timestamp: number * SEC_PER_BLOCK };
  });

  mockDeps.transactionHandler = mockTransactionHandler;
  mockDeps.claim = null;
  mockDeps.veaInbox = veaInbox;
  mockDeps.veaOutbox = veaOutbox;
  mockDeps.veaOutboxProvider = veaOutboxProvider;
  mockDeps.veaRouterProvider = veaRouterProvider;
  mockDeps.chainId = 10200;
  mockDeps.fetchLatestClaimedEpoch = jest.fn().mockResolvedValue({ stateRoot: "0xold" });
  // outboxBlock is deliberately a Sepolia-scale number: the code must not use it.
  mockDeps.fetchSettledReadBlocks = jest.fn().mockResolvedValue({ inboxBlock: 4242, outboxBlock: ROUTER_HEAD });

  await checkAndClaim(mockDeps);

  expect(veaOutbox.stateRoot).toHaveBeenCalledWith({ blockTag: OUTBOX_HEAD });
  expect(veaOutbox.stateRoot).not.toHaveBeenCalledWith({ blockTag: ROUTER_HEAD });

  expect(queriedRanges.length).toBeGreaterThan(0);
  for (const [from, to] of queriedRanges) {
    // Chiado range, never the Sepolia one.
    expect(from).toBeGreaterThan(ROUTER_HEAD);
    expect(to).toBeGreaterThan(ROUTER_HEAD);
    expect(to).toBeLessThanOrEqual(OUTBOX_HEAD);
  }
});

